use rk3588_boot_support::{BarrierOps,ByteTransfer,CacheRangeOps,DelayUs,MemoryTransfer,Mmio32};use crate::stage14::WakeTagSource;use crate::stage15::{PmuMcuResumeError,PmuMcuResumePath};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct PmuMcuCycleReport{pub image_saved:bool,pub resume:PmuMcuResumePath}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuCycleError{Resume(PmuMcuResumeError)}
/// Compose the recovered PMU-MCU save and resume halves. The literal 0x17C00
/// remains unit-distinct in stage13: DWORDs for copy, bytes for cache maintenance.
pub fn save_and_resume_pmumcu<I:Mmio32+DelayUs+BarrierOps+MemoryTransfer+ByteTransfer+CacheRangeOps>(io:&mut I,restore_enabled:bool,tags:WakeTagSource)->Result<PmuMcuCycleReport,PmuMcuCycleError>{let image_saved=crate::stage13::save_pmumcu_image(io);let resume=crate::stage15::resume_pmumcu(io,restore_enabled,image_saved,tags).map_err(PmuMcuCycleError::Resume)?;Ok(PmuMcuCycleReport{image_saved,resume})}
#[cfg(test)]mod tests{use super::*;struct M{copies:u8,cache:u8}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{crate::stage13::PMUMCU_MAGIC_ADDR=>crate::stage13::PMUMCU_MAGIC,crate::stage13::PMUMCU_SENTINEL_ADDR=>crate::stage13::PMUMCU_SENTINEL,0xFD7F0A00=>0x2000,0xFD8D4010=>0,_=>0}}fn write32(&mut self,_:u64,_:u32){}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}impl BarrierOps for M{fn dsb(&mut self){}fn isb(&mut self){}}impl MemoryTransfer for M{fn copy_words_exact(&mut self,_:u64,_:u64,_:u32){self.copies+=1}}impl ByteTransfer for M{fn copy_bytes_exact(&mut self,_:u64,_:u64,_:u32){}}impl CacheRangeOps for M{fn clean_invalidate_range(&mut self,_:u64,_:u32){self.cache+=1}}#[test]fn cycle(){let mut m=M{copies:0,cache:0};let r=save_and_resume_pmumcu(&mut m,true,WakeTagSource::Default{src:0x2000}).unwrap();assert!(r.image_saved);assert_eq!(r.resume,PmuMcuResumePath::RestoredImage);assert_eq!((m.copies,m.cache),(2,1));}}
